import requests


def api_call(url, method="GET", headers=None, params=None, payload=None, timeout=30):
    if not url or not isinstance(url, str):
        return {"error": "A valid 'url' string is required."}

    method = (method or "GET").upper()
    headers = dict(headers) if headers else {}
    request_kwargs = {"headers": headers, "params": params or {}, "timeout": timeout}

    if payload is not None:
        if isinstance(payload, (dict, list)):
            request_kwargs["json"] = payload
            headers.setdefault("Content-Type", "application/json")
        else:
            request_kwargs["data"] = str(payload)

    try:
        response = requests.request(method, url, **request_kwargs)
    except requests.exceptions.Timeout:
        return {"error": "Request timed out after %s seconds." % timeout, "url": url}
    except requests.exceptions.RequestException as exc:
        return {"error": "Request failed: %s" % exc, "url": url}

    try:
        parsed = response.json()
    except ValueError:
        parsed = None

    return {
        "status_code": response.status_code,
        "ok": response.ok,
        "url": response.url,
        "headers": dict(response.headers),
        "json": parsed,
        "text": response.text[:5000] if parsed is None else None,
    }

