import urllib.request
import urllib.parse
import re
import html as _html

_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
       "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0 Safari/537.36")


def _fetch(url):
    req = urllib.request.Request(url, headers={
        "User-Agent": _UA,
        "Accept-Language": "en-US,en;q=0.9",
    })
    with urllib.request.urlopen(req, timeout=15) as resp:
        return resp.read().decode("utf-8", "replace")


def _clean(s):
    s = re.sub(r"<[^>]+>", "", s)
    return _html.unescape(s).strip()


def _unwrap(u):
    if u.startswith("//"):
        u = "https:" + u
    qs = urllib.parse.parse_qs(urllib.parse.urlparse(u).query)
    if "uddg" in qs:
        return qs["uddg"][0]
    return u


def _parse_bing(page, max_results):
    out = []
    for item in re.findall(r'<li class="b_algo".*?</li>', page, re.S):
        m = re.search(r'<h2[^>]*>\s*<a[^>]*href="([^"]+)"[^>]*>(.*?)</a>', item, re.S)
        if not m:
            continue
        sn = re.search(r'<p[^>]*>(.*?)</p>', item, re.S)
        out.append({
            "title": _clean(m.group(2)),
            "url": _unwrap(_html.unescape(m.group(1))),
            "snippet": _clean(sn.group(1)) if sn else "",
        })
        if len(out) >= max_results:
            break
    return out


def _parse_ddg(page, max_results):
    out = []
    blocks = re.findall(
        r'<a[^>]+class="result__a"[^>]*href="([^"]+)"[^>]*>(.*?)</a>(.*?)(?=<a[^>]+class="result__a"|$)',
        page, re.S)
    for href, title, rest in blocks:
        sn = re.search(r'class="result__snippet"[^>]*>(.*?)</a>', rest, re.S)
        out.append({
            "title": _clean(title),
            "url": _unwrap(_html.unescape(href)),
            "snippet": _clean(sn.group(1)) if sn else "",
        })
        if len(out) >= max_results:
            break
    return out


def web_search(query, max_results=5):
    """Search the web and return titles, URLs and snippets.

    Tries Bing first (reachable from the CN-hosted backend), then DuckDuckGo.
    """
    try:
        max_results = int(max_results)
    except (TypeError, ValueError):
        max_results = 5
    max_results = max(1, min(max_results, 10))

    q = urllib.parse.urlencode({"q": query})
    engines = [
        ("bing", "https://www.bing.com/search?" + q, _parse_bing),
        ("duckduckgo", "https://html.duckduckgo.com/html/?" + q, _parse_ddg),
    ]

    errors = []
    for name, url, parser in engines:
        try:
            page = _fetch(url)
        except Exception as exc:
            errors.append("%s: %s" % (name, exc))
            continue
        results = parser(page, max_results)
        if results:
            return {"query": query, "engine": name,
                    "count": len(results), "results": results}
        errors.append("%s: fetched but no results parsed" % name)

    return {"query": query, "error": "; ".join(errors), "results": []}

