def manage_storage(action, **params):
    """Create tables and read or write their rows."""
    _caller_agent_id = agent_id

    from app.core.database import SessionLocal
    from app import system_management

    db = SessionLocal()
    try:
        return system_management.manage_storage(
            db, action, caller_agent_id=_caller_agent_id, **params
        )
    finally:
        db.close()

